import { afterAll, afterEach, beforeAll, beforeEach, describe, expect, test } from "bun:test";
import { mkdirSync, mkdtempSync, readdirSync, realpathSync, renameSync, rmSync, symlinkSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { recordedInvocations, writeStub, type Invocation } from "../src/execute";
import { createFixture, wardLauncher, type Fixture } from "../src/fixture";
import { cleanupOwnedProcesses } from "../src/process";
import { Defect, Host } from "./host";

// Executes the plugins generated by the real `ward integrate opencode`
// against the pinned @opencode/plugin package, with a recording `ward` stub on PATH.
// Bun.spawn resolves executables against the PATH the process started with, so `bun run test`
// starts the suite with only the stub directory and system directories on PATH.
const STUB_DIR = join(import.meta.dir, ".stub-bin");

const CHECK = ["check", "--profile", "edit", "--format", "json", "--learn-after", "3"];
const checkFor = (...paths: string[]) => [...CHECK, ...paths.flatMap((path) => ["--path", path])];

let fixture: Fixture;
let work: string;
let logDir: string;
let responses: string;
let otherCheckout: string;
const loaded: (() => Promise<void> | void)[] = [];

beforeAll(async () => {
  if (process.env.PATH !== `${STUB_DIR}:/usr/bin:/bin`) {
    throw new Error("run this suite with `bun run test` so only the recording stub can be spawned");
  }
  fixture = await createFixture({ harness: "opencode", ward: wardLauncher(process.env)! });
  // Project plugins resolve @opencode/plugin through the host; the fixture links the pinned package.
  symlinkSync(join(import.meta.dir, "node_modules"), join(fixture.root, "node_modules"));
  work = mkdtempSync(join(tmpdir(), "ward-opencode-"));
  writeStub(STUB_DIR);
  otherCheckout = realpathSync(mkdtempSync(join(tmpdir(), "ward-opencode-checkout-")));
});

afterAll(() => {
  fixture?.cleanup();
  rmSync(work, { recursive: true, force: true });
  rmSync(otherCheckout, { recursive: true, force: true });
  cleanupOwnedProcesses();
});

// Spawned processes see the startup environment only, so the stub reads its log and responses
// from its own state directory, which is reset for every test.
const STATE = join(STUB_DIR, ".state");
let sequence = 0;
beforeEach(() => {
  sequence++;
  rmSync(STATE, { recursive: true, force: true });
  logDir = join(STATE, "log");
  responses = join(STATE, "responses");
  mkdirSync(responses, { recursive: true });
});

afterEach(async () => {
  while (loaded.length) await loaded.pop()!();
});

function respond(key: string, exit: number, stdout = "", stderr = "", delaySeconds = 0): void {
  const dir = join(responses, key);
  mkdirSync(dir, { recursive: true });
  writeFileSync(join(dir, "exit"), String(exit));
  writeFileSync(join(dir, "stdout"), stdout);
  writeFileSync(join(dir, "stderr"), stderr);
  if (delaySeconds > 0) writeFileSync(join(dir, "delay"), String(delaySeconds));
}

/** Runs `body` while the stub is absent, so spawning `ward` fails like a missing install. */
async function withoutWard(body: () => Promise<void>): Promise<void> {
  const stub = join(STUB_DIR, "ward");
  renameSync(stub, `${stub}.hidden`);
  try {
    await body();
  } finally {
    renameSync(`${stub}.hidden`, stub);
  }
}

const invocations = (): Invocation[] => recordedInvocations(logDir);

async function load(file: string): Promise<any> {
  return (await import(`${fixture.root}/.opencode/plugins/${file}?run=${sequence}-${Math.random()}`)).default;
}

async function setup(file: string, host: Host): Promise<() => Promise<void>> {
  const plugin = await load(file);
  const cleanup = await plugin.setup(host.context());
  let done = false;
  const dispose = async () => {
    if (done) return;
    done = true;
    await cleanup?.();
  };
  loaded.push(dispose);
  return dispose;
}

function sessionHost(): Host {
  const host = new Host(fixture.root);
  host.sessions.set("s1", fixture.root);
  return host;
}

describe("generated plugin definitions", () => {
  test("the plugin loads against the pinned package and declares its ID, and it is the only one", async () => {
    expect((await load("ward-edit-write.js")).id).toBe("ward.edit-write");
    expect(readdirSync(join(fixture.root, ".opencode/plugins"))).toEqual(["ward-edit-write.js"]);
  });

  test("an invalid plugin entrypoint fails instead of being silently skipped", async () => {
    await expect(import("data:text/javascript,export default")).rejects.toThrow();
  });
});

describe("post-edit quality check", () => {
  test("a completed edit runs the check with exact argv and cwd, and success is silent", async () => {
    respond("check", 0, JSON.stringify({ passed: true }));
    const host = sessionHost();
    await setup("ward-edit-write.js", host);
    const { content } = await host.after({ tool: "edit", sessionID: "s1", input: { filePath: "src/A.java" }, result: { content: "Edit applied." } });
    expect(invocations().map((i) => [i.argv, i.cwd, i.stdin])).toEqual([[checkFor("src/A.java"), realpathSync(fixture.root), ""]]);
    expect(content).toEqual([{ type: "text", text: "Edit applied." }]);
  });

  test("a failing check is delivered in the result the model reads without crashing the call", async () => {
    respond("check", 1, JSON.stringify({ passed: false, gates: [{ id: "format", status: "FAILED" }] }));
    const host = sessionHost();
    await setup("ward-edit-write.js", host);
    const { content } = await host.after({ tool: "write", sessionID: "s1", input: { filePath: "src/A.java" }, result: { content: "Wrote file." } });
    expect(content?.[0]).toEqual({ type: "text", text: "Wrote file." });
    const feedback = content?.slice(1).map((part) => part.text).join("\n") ?? "";
    expect(feedback).toContain("Ward quality check failed");
    expect(feedback).toContain('"status":"FAILED"');
  });

  test("learning prompts are delivered on a passing check", async () => {
    respond("check", 0, JSON.stringify({ passed: true, learning: { prompts: [{ instruction: "Run the formatter before editing." }] } }));
    const host = sessionHost();
    await setup("ward-edit-write.js", host);
    const { content } = await host.after({ tool: "edit", sessionID: "s1", input: { filePath: "a" }, result: { content: "ok" } });
    expect(content?.map((part) => part.text)).toEqual(["ok", "Run the formatter before editing."]);
  });

  test("learning prompts accompany a failing check", async () => {
    respond("check", 1, JSON.stringify({ passed: false, learning: { prompts: [{ instruction: "Keep tests green." }] } }));
    const host = sessionHost();
    await setup("ward-edit-write.js", host);
    const { content } = await host.after({ tool: "edit", sessionID: "s1", input: { filePath: "a" }, result: { content: "ok" } });
    expect(content?.map((part) => part.text).join("\n")).toContain("Keep tests green.");
  });

  test("an original tool failure is preserved and never triggers a check", async () => {
    const host = sessionHost();
    await setup("ward-edit-write.js", host);
    const { event } = await host.after({ tool: "edit", sessionID: "s1", input: {}, status: "error", error: { message: "no match" } });
    expect(event.error).toEqual({ message: "no match" });
    expect(invocations()).toEqual([]);
  });

  test("non-edit tools are ignored", async () => {
    const host = sessionHost();
    await setup("ward-edit-write.js", host);
    await host.after({ tool: "read", sessionID: "s1", input: { filePath: "a" }, result: { content: "x" } });
    expect(invocations()).toEqual([]);
  });

  test("structured output and metadata are preserved alongside feedback", async () => {
    respond("check", 1, "quality failed");
    const host = sessionHost();
    await setup("ward-edit-write.js", host);
    const metadata = { diff: "+a" };
    const { event, content } = await host.after({
      tool: "apply_patch",
      sessionID: "s1",
      input: { patchText: "*** Begin Patch" },
      result: { output: { applied: 1 }, metadata },
    });
    expect(event.result.output).toEqual({ applied: 1 });
    expect(event.result.metadata).toEqual(metadata);
    expect(content?.[0]).toEqual({ type: "text", text: '{"applied":1}' });
    expect(content?.slice(1).map((part) => part.text).join("\n")).toContain("quality failed");
  });

  test("a multi-file patch with a move passes each edited path to the check once", async () => {
    respond("check", 0, "{}");
    const host = sessionHost();
    await setup("ward-edit-write.js", host);
    const from = join(fixture.root, "docs/a/guide.md");
    const to = join(fixture.root, "docs/b/guide.md");
    await host.after({
      tool: "apply_patch",
      sessionID: "s1",
      input: { patchText: "*** Begin Patch" },
      result: { content: "done", metadata: { files: [{ filePath: from, movePath: to }, { filePath: join(fixture.root, "src/A.java") }, { filePath: from }] } },
    });
    expect(invocations().map((i) => i.argv)).toEqual([checkFor(from, to, join(fixture.root, "src/A.java"))]);
  });

  test("the newer patch tool's path argument targets the check", async () => {
    respond("check", 0, "{}");
    const host = sessionHost();
    await setup("ward-edit-write.js", host);
    await host.after({ tool: "patch", sessionID: "s1", input: { path: "docs/a/guide.md" }, result: { content: "ok" } });
    expect(invocations().map((i) => i.argv)).toEqual([checkFor("docs/a/guide.md")]);
  });

  test("an unavailable Ward executable is a bounded diagnostic, not a crashed call", async () => {
    const host = sessionHost();
    await setup("ward-edit-write.js", host);
    await withoutWard(async () => {
      const { content } = await host.after({ tool: "edit", sessionID: "s1", input: { filePath: "a" }, result: { content: "ok" } });
      expect(content?.map((part) => part.text).join("\n")).toContain("Ward could not run");
    });
  });
});

describe("session location", () => {
  test("checks run in the session's current location rather than the plugin location", async () => {
    respond("check", 0, "{}");
    const host = sessionHost();
    host.sessions.set("s2", otherCheckout);
    await setup("ward-edit-write.js", host);
    await host.after({ tool: "edit", sessionID: "s2", input: { filePath: "a" }, result: { content: "ok" } });
    expect(invocations().map((i) => i.cwd)).toEqual([otherCheckout]);
  });

  test("multiple checkouts and a moved session each use their current location", async () => {
    respond("check", 0, "{}");
    const host = sessionHost();
    host.sessions.set("s2", otherCheckout);
    await setup("ward-edit-write.js", host);
    await host.after({ tool: "edit", sessionID: "s1", input: { filePath: "a" }, result: { content: "ok" } });
    await host.after({ tool: "edit", sessionID: "s2", input: { filePath: "a" }, result: { content: "ok" } });
    host.sessions.set("s1", otherCheckout);
    await host.after({ tool: "edit", sessionID: "s1", input: { filePath: "a" }, result: { content: "ok" } });
    expect(invocations().map((i) => i.cwd)).toEqual([realpathSync(fixture.root), otherCheckout, otherCheckout]);
  });

  test("a failed location lookup skips the check instead of guessing a directory", async () => {
    const host = sessionHost();
    host.sessionLookupFails = true;
    await setup("ward-edit-write.js", host);
    const { content } = await host.after({ tool: "edit", sessionID: "s1", input: { filePath: "a" }, result: { content: "ok" } });
    expect(invocations()).toEqual([]);
    expect(content).toEqual([{ type: "text", text: "ok" }]);
  });
});

describe("plugin disposal", () => {
  test("unloading disposes the hook and drops a late check result", async () => {
    respond("check", 1, "late findings", "", 0.3);
    const host = sessionHost();
    const dispose = await setup("ward-edit-write.js", host);
    const pending = host.after({ tool: "edit", sessionID: "s1", input: { filePath: "a" }, result: { content: "ok" } });
    await Bun.sleep(50);
    await dispose();
    expect(host.toolHooks.get("execute.after")).toEqual([]);
    const { content } = await pending;
    expect(content).toEqual([{ type: "text", text: "ok" }]);
  });

  test("reloading leaves exactly one active observer", async () => {
    respond("check", 0, "{}");
    const host = sessionHost();
    const first = await setup("ward-edit-write.js", host);
    await first();
    await setup("ward-edit-write.js", host);
    expect(host.toolHooks.get("execute.after")?.length).toBe(1);
    await host.after({ tool: "edit", sessionID: "s1", input: { filePath: "a" }, result: { content: "ok" } });
    expect(invocations().length).toBe(1);
  });
});

test("the host emulation treats an execute.after rejection as a defect", async () => {
  const host = new Host("/tmp");
  host.toolHooks.set("execute.after", [() => Promise.reject(new Error("boom"))]);
  await expect(host.after({ tool: "edit", sessionID: "s1", input: {}, result: { content: "x" } })).rejects.toThrow(Defect);
});
